actions.script:
if (recoveryHolders && !ec.user.hasPermission('VAULT_RECOVERY')) { optionList = []; return }
const found = ec.service.sync().name('ironstone.shared.ChatterServices.search#Users').parameters({term: term || '', limit: 50}).call()
const users = Array.from(found?.userList || []).filter((user) => user.id !== ec.user.userId)
const ids = users.map((user) => user.id)
let keyed = new Set()
let holders = null
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (ids.length) keyed = new Set(Array.from(ec.entity.find('moqui.security.vault.VaultPersonalKey').condition('userId', 'in', ids)
        .condition('statusId', 'VpkActive').list()).map((key) => key.userId))
    if (recoveryHolders && ids.length) {
        const now = ec.user.nowTimestamp
        const groups = Array.from(ec.entity.find('moqui.security.UserGroupPermission').condition('userPermissionId', 'VAULT_RECOVERY')
            .conditionDate('fromDate', 'thruDate', now).list()).map((row) => row.userGroupId)
        holders = new Set(groups.length ? Array.from(ec.entity.find('moqui.security.UserGroupMember').condition('userGroupId', 'in', groups)
            .condition('userId', 'in', ids).conditionDate('fromDate', 'thruDate', now).list()).map((row) => row.userId) : [])
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
optionList = users.filter((user) => keyed.has(user.id) && (!holders || holders.has(user.id))).slice(0, 20)
    .map((user) => ({value: user.id, label: user.label}))

const asked = String(userIds || '').split(',').map((id) => id.trim()).filter((id) => id).slice(0, 200)
names = {}
if (!asked.length || !ec.user.userId) return
const me = ec.user.userId
const known = new Set([me])
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const find = (entity) => ec.entity.find('moqui.security.vault.' + entity)
    const recovery = ec.user.hasPermission('VAULT_RECOVERY')
    const now = ec.user.nowTimestamp
    const vaultIds = Array.from(new Set(Array.from(find('VaultMember').condition('userId', me).list()).map((row) => row.vaultId)
        .concat(Array.from(find('Vault').condition('ownerUserId', me).list()).map((row) => row.vaultId))))
    // the recovery keys a vault of the caller's lists as its member recovery:<id>
    const listedKeys = new Set()
    if (vaultIds.length) {
        for (const row of Array.from(find('VaultMember').condition('vaultId', 'in', vaultIds).list())) {
            known.add(row.userId)
            if (String(row.userId || '').startsWith('recovery:')) listedKeys.add(String(row.userId).slice('recovery:'.length))
        }
        for (const row of Array.from(find('VaultKeyVersion').condition('vaultId', 'in', vaultIds).list())) known.add(row.signerUserId)
    }
    for (const row of Array.from(find('VaultDelivery').condition('recipientUserId', me).list())) known.add(row.senderId)
    for (const row of Array.from(find('VaultKeyCheck').condition('checkerUserId', me).list())) known.add(row.checkedUserId)
    const liveKeys = Array.from(find('VaultRecoveryKey').conditionDate('fromDate', 'thruDate', now).list())
    for (const row of liveKeys) known.add(row.makerUserId)
    const holderKeys = liveKeys.map((row) => row.recoveryKeyId).filter((id) => recovery || listedKeys.has(id))
    if (holderKeys.length) for (const row of Array.from(find('VaultRecoveryHolder').condition('recoveryKeyId', 'in', holderKeys)
        .conditionDate('fromDate', 'thruDate', now).list())) known.add(row.userId)
    if (recovery) for (const row of Array.from(find('VaultRecoverySession').list())) {
        known.add(row.subjectUserId)
        known.add(row.holderUserId)
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
const ids = asked.filter((id) => known.has(id))
if (!ids.length) return
const checked = ec.service.sync().name('org.moqui.chat.ChatServices.get#RefusedUsers').parameters({userIdList: ids, hook: 'chat-target'}).call()
const refused = new Set(checked ? Array.from(checked.refusedUserIdList || []) : ids)
const reach = ids.filter((id) => id === me || !refused.has(id))
if (!reach.length) return
const accounts = ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', reach).disableAuthz().list()
for (const account of Array.from(accounts))
    names[account.userId] = account.userFullName ? account.userFullName + ' (' + account.username + ')' : account.username

optionList = []
if (!ec.user.hasPermission('VAULT_RECOVERY')) return
const text = String(term || '').trim().toLowerCase()
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const ids = Array.from(new Set(Array.from(ec.entity.find('moqui.security.UserGroupPermission').condition('userPermissionId', 'VAULT_RECOVERY')
        .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp).list()).map((row) => row.userGroupId)))
    const groups = ids.length ? Array.from(ec.entity.find('moqui.security.UserGroup').condition('userGroupId', 'in', ids).list()) : []
    optionList = groups.map((group) => ({value: group.userGroupId, label: group.description || group.userGroupId}))
        .filter((option) => !text || option.label.toLowerCase().includes(text) || option.value.toLowerCase().includes(text)).slice(0, 50)
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
